mapper.select:
SELECT m.BEGIN_STAT_CODE entryStationCode, es.STATION_NM entryStationName, m.END_STAT_CODE exitStationCode, xs.STATION_NM exitStationName, m.FARE_TIER fareTier, f.TICKET_PRICE ticketPrice FROM TBL_FARE_MATRIX m INNER JOIN TBL_BASE_FARE f ON f.PARA_VER_NO = m.PARA_VER_NO AND f.FARE_TIER = m.FARE_TIER AND f.FARE_TYPE = 0 LEFT JOIN TBL_STATION_INFO es ON es.PARA_VER_NO = (SELECT CURRENT_VER_NO FROM TBL_PARA_VERSION WHERE PARA_TYPE = '0001') AND es.STATION_CODE = m.BEGIN_STAT_CODE LEFT JOIN TBL_STATION_INFO xs ON xs.PARA_VER_NO = (SELECT CURRENT_VER_NO FROM TBL_PARA_VERSION WHERE PARA_TYPE = '0001') AND xs.STATION_CODE = m.END_STAT_CODE WHERE m.PARA_VER_NO = (SELECT CURRENT_VER_NO FROM TBL_PARA_VERSION WHERE PARA_TYPE = '0004')
AND m.BEGIN_STAT_CODE = #{entryStationCode,jdbcType=VARCHAR}
AND m.END_STAT_CODE = #{exitStationCode,jdbcType=VARCHAR}
AND m.BEGIN_STAT_CODE IN (SELECT STATION_CODE FROM TBL_STATION_INFO WHERE PARA_VER_NO = (SELECT CURRENT_VER_NO FROM TBL_PARA_VERSION WHERE PARA_TYPE = '0001') AND OWNER_LINE_ID = #{entryLineCode,jdbcType=VARCHAR})
AND m.END_STAT_CODE IN (SELECT STATION_CODE FROM TBL_STATION_INFO WHERE PARA_VER_NO = (SELECT CURRENT_VER_NO FROM TBL_PARA_VERSION WHERE PARA_TYPE = '0001') AND OWNER_LINE_ID = #{exitLineCode,jdbcType=VARCHAR})
ORDER BY m.BEGIN_STAT_CODE, m.END_STAT_CODE

SELECT STATION_CODE stationCode, STATION_NM stationName FROM TBL_STATION_INFO WHERE PARA_VER_NO = (SELECT CURRENT_VER_NO FROM TBL_PARA_VERSION WHERE PARA_TYPE = '0001')
AND OWNER_LINE_ID = #{lineCode,jdbcType=VARCHAR}
ORDER BY STATION_CODE
